      "WITH Ranked AS (\n SELECT EmployeeId, DepartmentId, Salary,\n DENSE_RANK() OVER (PARTITION BY DepartmentId ORDER BY Salary DESC) AS r\n FROM Employees WHERE Salary IS NOT NULL\n)\nSELECT * FROM Ranked WHERE r <= 3;",
